import { InsufficientStockError, InvalidValueError } from './DomainErrors';
import { OrderLine } from './OrderLine';
import { Product } from './Product';

/**
 * Domain service: applies an order's lines to the stock of several products at once.
 * Reservation is all-or-nothing: every line is checked before any product is changed.
 */
export class StockAllocationService {
  reserve(lines: readonly OrderLine[], products: ReadonlyMap<string, Product>): void {
    const consolidated = OrderLine.consolidate(lines);
    for (const line of consolidated) {
      const product = this.productFor(line, products);
      if (!product.canReserve(line.quantity)) {
        throw new InsufficientStockError(product.id, line.quantity, product.available);
      }
    }
    for (const line of consolidated) {
      this.productFor(line, products).reserve(line.quantity);
    }
  }

  release(lines: readonly OrderLine[], products: ReadonlyMap<string, Product>): void {
    for (const line of lines) {
      this.productFor(line, products).release(line.quantity);
    }
  }

  dispatch(lines: readonly OrderLine[], products: ReadonlyMap<string, Product>): void {
    for (const line of lines) {
      this.productFor(line, products).dispatch(line.quantity);
    }
  }

  private productFor(line: OrderLine, products: ReadonlyMap<string, Product>): Product {
    const product = products.get(line.productId);
    if (product === undefined) {
      throw new InvalidValueError(`Product ${line.productId} was not supplied for allocation`);
    }
    return product;
  }
}

